import {renderCompanyBackground} from './intel-background.mjs';
import {renderNetworking} from './intel-networking.mjs';
import {milestoneStyle,extraDrawings} from './intel-vectors.mjs';
import {escapeHtml as esc,safeUrl,selectEvidence} from './core.mjs';
import {companyLogo} from './company-logos.mjs';
export const intelTabs=['overview','predictions','patterns','actions'];
const labels={overview:'Company story',predictions:'Predictions',patterns:'Hiring patterns',actions:'Your next steps'};
const date=d=>validDate(d)?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Date unknown';
function validDate(d){return typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d));}
const para=t=>`<p>${esc(t||'Not recorded in this research snapshot.')}</p>`;
const link=(url,label='Read original source ↗')=>safeUrl(url)?`<a class="source-link" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(url))}">${esc(label)}</a>`:'';
export function evidenceFor(atlas,name){return selectEvidence(atlas?.evidence||[],atlas?.companies?.[name]?.evidence||[]).filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i);}
export function timelineFor(evidence){return evidence.map(e=>({...e,timelineDate:validDate(e.published)?e.published:validDate(e.observed)?e.observed:'',dateKind:validDate(e.published)?'Published':'Discovered'})).sort((a,b)=>(a.timelineDate||'9999').localeCompare(b.timelineDate||'9999')||a.id.localeCompare(b.id));}
export function cycleCounts(evidence){const counts=new Map();for(const e of evidence){const cycle=/^C\d+/.exec(e.id)?.[0]||'Other';counts.set(cycle,(counts.get(cycle)||0)+1);}return [...counts].sort(([a],[b])=>a.localeCompare(b)).map(([label,count])=>({label,count}));}
export function renderEvidence(e){return `<article class="intel-evidence"><span class="intel-kicker">${esc(e.id)} · Published ${date(e.published)} · Checked ${date(e.observed)}</span>${para(e.fact)}${e.limitation?`<p class="intel-caution">${esc(e.limitation)}</p>`:''}${link(e.url)}</article>`;}
function chart(evidence){const bins=cycleCounts(evidence),max=Math.max(1,...bins.map(b=>b.count));return `<figure class="intel-chart"><figcaption><span class="intel-kicker">RESEARCH COVERAGE</span><h3>Evidence across reviews</h3><p>Records retained for this company by research cycle.</p></figcaption><div class="intel-bars" role="img" aria-label="${esc(bins.map(b=>`${b.label}: ${b.count} evidence records`).join('; ')||'No evidence records')}">${bins.map(b=>`<div class="intel-bar-row"><span>${esc(b.label)}</span><div><i style="width:${b.count/max*100}%"></i></div><b>${b.count}</b></div>`).join('')}</div><p class="intel-caption">Counts describe this archive, not job openings, hiring growth or the chance of an offer.</p></figure>`;}
function timeline(evidence){const items=timelineFor(evidence);const colours=['#9fc3f4','#7ed5ce','#c6db8e','#f3cd76','#dba8d9','#f1a88c'];return `<section class="intel-panel intel-story" aria-label="Company timeline"><div class="intel-section-head"><div><span class="intel-kicker">THE COMPANY STORY</span><h3>From signals to your next move</h3><p>Explore the evidence in time. Click a milestone for its full briefing.</p></div><div class="intel-scroll-controls"><button class="btn outline small" data-action="intel-scroll" data-direction="-1" aria-label="Earlier milestones">←</button><button class="btn outline small" data-action="intel-scroll" data-direction="1" aria-label="Later milestones">→</button></div></div><div class="intel-timeline intel-visual-timeline" tabindex="0" aria-label="Scrollable evidence timeline">${items.map((e,i)=>{const style=milestoneStyle({title:e.fact}),drawing=extraDrawings[style.icon]||extraDrawings.document;return `<button class="intel-milestone intel-visual-milestone ${i%2?'below':'above'}" style="--milestone:${colours[i%colours.length]}" data-action="intel-evidence" data-id="${esc(e.id)}"><span class="intel-milestone-copy"><span class="intel-year">${e.timelineDate?e.timelineDate.slice(0,4):'Undated'}</span><span class="intel-date">${date(e.timelineDate)}</span><span class="intel-kicker">${e.timelineDate?e.dateKind:'Undated'} evidence · ${esc(e.id)}</span><strong>${esc(style.title)}</strong><span class="intel-preview">${esc(e.fact)}</span><span class="intel-expand">Expand briefing ↗</span></span><span class="intel-vector"><svg viewBox="0 0 130 130" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">${drawing}</svg><span class="intel-node">${i+1}</span></span><span class="intel-connector"></span><span class="intel-track-dot"></span></button>`;}).join('')||'<p>No dated evidence available.</p>'}</div><p class="intel-caption">Scroll left to right. Colours distinguish milestones, not evidence quality. Equal spacing is illustrative; publication and discovery dates are labelled separately.</p></section>`;}

function predictions(c){return `<div class="intel-forecast"><span class="intel-kicker">POSSIBLE OUTCOME · NOT CONFIRMED</span><h3>What could happen next</h3>${para(c.forecast?.text)}<div class="intel-forecast-meta"><span>Review deadline <b>${date(c.forecast?.deadline)}</b></span><span>Evidence strength <b>${esc(c.forecast?.strength||'Not rated in this snapshot')}</b></span></div></div><div class="intel-two"><article class="intel-case positive"><span class="intel-kicker">SUPPORTING CASE</span><h3>Why it could happen</h3>${para(c.bull)}${c.bullLimits?para(c.bullLimits):''}</article><article class="intel-case caution"><span class="intel-kicker">COUNTEREVIDENCE</span><h3>What could get in the way</h3>${para(c.bear)}${c.bearLimits?para(c.bearLimits):''}</article></div><details class="intel-accordion" open><summary>Forecast review & outcome</summary>${para(c.forecast?.outcome)}${para(c.audit)}</details><p class="intel-caption">A research hypothesis is not a vacancy, a hiring probability or a confirmed outcome.</p>`;}
function patterns(evidence){const years=new Map();for(const e of timelineFor(evidence)){const year=validDate(e.published)?e.published.slice(0,4):'Publication date unknown';if(!years.has(year))years.set(year,[]);years.get(year).push(e);}return `<div class="intel-two">${chart(evidence)}<article class="intel-case"><span class="intel-kicker">READ THE PATTERN CAREFULLY</span><h3>Research history, not a hiring calendar.</h3><p>Explore dated announcements, role requirements and programme evidence below. Repeated research checks do not establish seasonal hiring or net-new jobs.</p><p>Missing years mean this snapshot has no linked evidence for that year. They do not mean the employer stopped hiring.</p></article></div>${[...years].sort(([a],[b])=>a.localeCompare(b)).map(([year,items])=>`<details class="intel-accordion"><summary><span>${esc(year)}</span><small>${items.length} evidence records</small></summary>${items.map(renderEvidence).join('')}</details>`).join('')}`;}
function actions(c,profile){return `<div class="intel-action"><span class="intel-kicker">TURN RESEARCH INTO A CONVERSATION</span><h3>A more informed next move.</h3>${para(c.action)}</div><div class="intel-steps"><article><b>01</b><h4>Check the opportunity</h4><p>Reopen the employer’s source. Confirm availability, graduation dates and role-specific eligibility.</p></article><article><b>02</b><h4>Prepare your evidence</h4><p>Choose a project relevant to ${esc(profile?.focus?.toLowerCase()||'your career goals')}. Explain your contribution and a measurable result.</p></article><article><b>03</b><h4>Find the right conversation</h4><p>Ask who owns the relevant work and what an early-career candidate should demonstrate.</p><button class="text-button" data-action="nav" data-view="network">Explore my network →</button></article></div><p class="intel-caption">The archived company recommendation uses the original marketing/MSBA reference profile. The preparation prompt reflects your selected profile; it is not a new AI assessment.</p>`;}
export function renderIntel(atlas,{company,tab='overview',query='',profile,saved=false}={}){
 const names=Object.keys(atlas.companies||{}).filter(n=>!query||n.toLowerCase().includes(query.toLowerCase()));
 const selected=names.includes(company)?company:names[0];const c=atlas.companies[selected];
 const search=`<div class="intel-controls"><label class="search-wrap"><input data-search="companies" type="search" value="${esc(query)}" placeholder="Find a company" aria-label="Find a company"></label>${c?`<label class="intel-select">Choose a company<select id="intelCompany">${names.map(n=>`<option ${n===selected?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`:''}</div>`;
 if(!c)return search+'<div class="empty">No companies match this search. <button class="text-button" data-action="clear">Clear filters</button></div>';
 const ev=evidenceFor(atlas,selected),active=intelTabs.includes(tab)?tab:'overview';
 const body=active==='overview'?`<div class="intel-two"><article class="intel-case"><span class="intel-kicker">THE CURRENT PICTURE</span><h3>What the research says</h3>${para(c.assessment)}<p class="intel-caption">Original reference: marketing-experienced MSBA student graduating August 2027. Not recalculated for each demo profile.</p></article>${chart(ev)}</div>`:active==='predictions'?predictions(c):active==='patterns'?`<div class="intel-original"><p class="archive-label">HISTORICAL RESEARCH · COLLECTED 31 OCT 2026 · NOT LIVE</p>${renderCompanyBackground(atlas,selected)}</div>`:actions(c,profile)+`<div class="intel-original">${renderNetworking(selected)}</div>`;
 return `<div class="intel-workspace"><section class="intel-hero"><div><span class="intel-kicker">ATLAS.ai / COMPANY INTELLIGENCE</span><h2>See the story.<br><em>Find your next move.</em></h2><p>Connect company signals, the evidence behind them and the conversations worth starting.</p></div><div class="intel-orbit" aria-hidden="true"><span>ATLAS<span>.ai</span></span><i></i><i></i><i></i></div><div class="intel-status"><span class="intel-live-dot"></span> Archived review ${esc(atlas.cycle)} · ${date(atlas.asOf)} · ${Object.keys(atlas.companies).length} companies · Not a live feed</div></section>${search}<header class="intel-company"><div class="intel-company-name">${companyLogo(selected)}<div><span class="intel-kicker">SELECTED COMPANY</span><h2>${esc(selected)}</h2></div></div><button class="btn outline" data-action="save" data-id="${esc('company:'+selected)}" data-type="company">${saved?'✓ Following company':'+ Follow company'}</button></header><div class="intel-metrics"><div><strong>${ev.length}</strong><span>Linked evidence records</span></div><div><strong>${new Set(ev.map(e=>e.url).filter(Boolean)).size}</strong><span>Distinct source URLs</span></div><div><strong>${date(c.asOf)}</strong><span>Last archived review</span></div></div>${timeline(ev)}<div class="intel-tabs" role="tablist" aria-label="Company intelligence sections">${intelTabs.map(t=>`<button id="intel-tab-${t}" role="tab" aria-selected="${t===active}" aria-controls="intel-panel-${t}" tabindex="${t===active?0:-1}" data-action="intel-tab" data-tab="${t}">${labels[t]}</button>`).join('')}</div><section class="intel-tab-panel" id="intel-panel-${active}" role="tabpanel" aria-labelledby="intel-tab-${active}">${body}</section><details class="intel-accordion"><summary>Sources & full dossier <small>${ev.length} records</small></summary>${ev.map(renderEvidence).join('')}<a class="btn outline small" href="atlas-data.json" download>Download research snapshot</a></details><details class="intel-accordion"><summary>About these insights</summary><p>Public-source research retained from Zal Career Command. This demo uses the ${esc(atlas.cycle)} snapshot dated ${date(atlas.asOf)}; reloading does not run new research. Source dates and discovery dates are different. Recheck current roles and requirements before acting.</p>${para(c.audit)}</details></div>`;
}
